from textual.app import App, ComposeResult, on
from textual.message import Message
from textual.widgets import Button, Static, Header

class MyWidget(Static):
    """Widget containing a button that sends custom messages."""

    class ButtonPressed(Message):
        """Sent when the button in MyWidget is pressed."""

        def __init__(self, label: str):
            super().__init__()
            self.label = label

    def compose(self) -> ComposeResult:
        yield Button("Click Me")

    def on_button_pressed(self, event: Button.Pressed) -> None:
        self.post_message(self.ButtonPressed(event.button.label))

class MyApp(App):
    def compose(self) -> ComposeResult:
        yield Header()
        yield MyWidget()

    @on(MyWidget.ButtonPressed)
    def handle_button_pressed(self, message: MyWidget.ButtonPressed) -> None:
        self.notify(f"Button pressed: {message.label}")

if __name__ == "__main__":
    MyApp().run()

